def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and collect yesterday bids
    alive_opps = []
    yesterday_bids = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append(o)
            prev = o.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    yesterday_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    # If nobody alive, bid conservatively
    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Baseline from yesterday: use median-ish target to undercut average
    if yesterday_bids:
        sorted_b = sorted(yesterday_bids)
        n = len(sorted_b)
        median_bid = sorted_b[n // 2] if n % 2 == 1 else 0.5 * (sorted_b[n // 2 - 1] + sorted_b[n // 2])
        # Undercut slightly to avoid overpaying; but not too low.
        target = median_bid * 0.92
    else:
        target = DAILY_SALARY * 0.55

    # Pressure adjustment based on my hp / no-water days
    hp = float(my_status['hp'])
    no_water_days = int(my_status.get('no_water_days', 0))
    budget = float(my_status['budget'])

    # If I'm in danger, bid more aggressively
    if hp <= 2 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.85)
    elif hp <= 4:
        target = max(target, DAILY_SALARY * 0.65)

    # Supply-based adjustment: higher supply reduces need; lower supply increases need
    if supply <= MIN_SUPPLY + 0.5:
        target *= 1.08
    elif supply >= MAX_SUPPLY - 0.5:
        target *= 0.95

    # Clamp to feasible range
    bid = max(0.0, min(budget, target))

    # Ensure we don't bid trivially low when others likely bid mid-high
    if yesterday_bids and bid < DAILY_SALARY * 0.45:
        bid = min(budget, DAILY_SALARY * 0.55)

    return float(bid)

